package com.bank.kyc.service;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Smallest stretch of the arrival stream that contains a complete KYC packet.
public class KycPacketMatcher {
    private static final Logger log = Logger.getLogger(KycPacketMatcher.class.getName());

    public String smallestCompletePacket(String stream, String required) {
        if (stream == null || required == null || required.isEmpty()
                || stream.length() < required.length()) {
            return "";
        }
        Map<Character, Integer> need = new HashMap<>();
        for (char c : required.toCharArray()) {
            need.merge(c, 1, Integer::sum);
        }
        int requirements = need.size();
        Map<Character, Integer> window = new HashMap<>();
        int formed = 0;
        int left = 0;
        int bestLen = Integer.MAX_VALUE;
        int bestStart = 0;

        for (int right = 0; right < stream.length(); right++) {
            char c = stream.charAt(right);
            if (need.containsKey(c)) {
                int cnt = window.merge(c, 1, Integer::sum);
                if (cnt == need.get(c)) {
                    formed++;
                }
            }
            // When complete, shrink from the left as far as still complete.
            while (formed == requirements) {
                if (right - left + 1 < bestLen) {
                    bestLen = right - left + 1;
                    bestStart = left;
                }
                char lc = stream.charAt(left);
                if (need.containsKey(lc)) {
                    int cnt = window.merge(lc, -1, Integer::sum);
                    if (cnt < need.get(lc)) {
                        formed--;
                    }
                }
                final int ls = left;
                log.fine(() -> "Packet complete; shrinking from left " + ls);
                left++;
            }
        }
        String result = (bestLen == Integer.MAX_VALUE)
                ? "" : stream.substring(bestStart, bestStart + bestLen);
        final String r = result;
        log.info(() -> "Smallest complete packet in '" + stream + "' needing '"
                + required + "' = '" + r + "'");
        return result;
    }
}
