package com.bank.kyc;

import com.bank.kyc.model.Account;
import com.bank.kyc.service.KycPacketMatcher;

import java.math.BigDecimal;
import java.util.Date;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class MinWindowSubstringDemo {
    private static final Logger log = Logger.getLogger(MinWindowSubstringDemo.class.getName());

    public static void main(String[] args) {
        setupLogging();
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        KycPacketMatcher matcher = new KycPacketMatcher();
        String required = "AAI"; // 2 address proofs + 1 identity proof

        String rajeshStream = "APAIAPI"; // A=addr I=identity P=photo
        log.info(() -> rajesh.getHolderName() + " (" + rajesh.getAccountId()
                + ") stream=" + rajeshStream);
        String r1 = matcher.smallestCompletePacket(rajeshStream, required);
        log.info(() -> rajesh.getHolderName() + " smallest packet = '" + r1 + "'");

        String priyaStream = "PAPIP"; // only one address → incomplete
        log.info(() -> priya.getHolderName() + " (" + priya.getAccountId()
                + ") stream=" + priyaStream);
        String r2 = matcher.smallestCompletePacket(priyaStream, required);
        log.info(() -> priya.getHolderName() + " smallest packet = '" + r2 + "'");
    }

    private static void setupLogging() {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.FINE);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.FINE);
    }

    static class BankLogFormatter extends Formatter {
        @Override
        public String format(LogRecord r) {
            return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                    new Date(r.getMillis()), r.getLevel(), r.getMessage());
        }
    }
}
